-- C11 / P11.1 — owner-scoped books registry, extensible book types, and immutable hierarchy lineage.
create table if not exists public.command_center_book_author_identity_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 author_event_id text not null check(btrim(author_event_id)<>''), author_id text not null check(btrim(author_id)<>''), display_name text not null check(btrim(display_name)<>''), aliases text[] not null default '{}'::text[], source_refs text[] not null check(cardinality(source_refs)>0), observed_at timestamptz not null, version integer not null check(version>0),
 primary key(owner_id,author_event_id), unique(owner_id,author_id,version)
);
create table if not exists public.command_center_book_type_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 type_event_id text not null check(btrim(type_event_id)<>''), type_key text not null check(btrim(type_key)<>''), label text not null check(btrim(label)<>''), renderer_key text not null check(btrim(renderer_key)<>''), allowed_relationship_kinds text[] not null check(cardinality(allowed_relationship_kinds)>0), source_refs text[] not null check(cardinality(source_refs)>0), observed_at timestamptz not null, version integer not null check(version>0),
 primary key(owner_id,type_event_id), unique(owner_id,type_key,version), check(allowed_relationship_kinds <@ array['standalone','series','trilogy','collection','umbrella']::text[])
);
create table if not exists public.command_center_book_registry_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 book_event_id text not null check(btrim(book_event_id)<>''), book_id text not null check(btrim(book_id)<>''), project_id text not null check(btrim(project_id)<>''), author_id text not null check(btrim(author_id)<>''), canonical_title text not null check(btrim(canonical_title)<>''),
 relationship_kind text not null check(relationship_kind in ('standalone','series','trilogy','collection','umbrella')), node_role text not null check(node_role in ('work','container')), parent_book_id text, sequence integer, formats text[] not null default '{}'::text[], book_type text not null check(btrim(book_type)<>''), source_refs text[] not null check(cardinality(source_refs)>0), observed_at timestamptz not null, version integer not null check(version>0),
 primary key(owner_id,book_event_id), unique(owner_id,book_id,version), check(parent_book_id is null or btrim(parent_book_id)<>''), check((parent_book_id is null and sequence is null) or (parent_book_id is not null and sequence is not null and sequence>0)), check((node_role='work' and relationship_kind='standalone' and cardinality(formats)>0) or (node_role='container' and relationship_kind<>'standalone')),
 check(formats <@ array['kindle','paperback','hardcover','digital_other']::text[])
);
create or replace view public.command_center_book_authors_current with (security_invoker=true) as select distinct on(owner_id,author_id) owner_id,author_event_id,author_id,display_name,aliases,source_refs,observed_at,version from public.command_center_book_author_identity_history order by owner_id,author_id,version desc,observed_at desc;
create or replace view public.command_center_book_types_current with (security_invoker=true) as select distinct on(owner_id,type_key) owner_id,type_event_id,type_key,label,renderer_key,allowed_relationship_kinds,source_refs,observed_at,version from public.command_center_book_type_history order by owner_id,type_key,version desc,observed_at desc;
create or replace view public.command_center_books_current with (security_invoker=true) as select distinct on(owner_id,book_id) owner_id,book_event_id,book_id,project_id,author_id,canonical_title,relationship_kind,node_role,parent_book_id,sequence,formats,book_type,source_refs,observed_at,version from public.command_center_book_registry_history order by owner_id,book_id,version desc,observed_at desc;
create or replace function public.command_center_validate_book_registry_insert() returns trigger language plpgsql set search_path to 'public' as $$
declare parent_kind text; parent_role text; allowed text[]; current_project text; current_author text; current_type text; current_role text; current_kind text; current_parent text; sibling_count integer; begin
 if not exists(select 1 from public.command_center_book_authors_current a where a.owner_id=new.owner_id and a.author_id=new.author_id) then raise exception 'Book requires exact owner-scoped author identity'; end if;
 select allowed_relationship_kinds into allowed from public.command_center_book_types_current t where t.owner_id=new.owner_id and t.type_key=new.book_type; if allowed is null then raise exception 'Unregistered book type'; end if; if not(new.relationship_kind=any(allowed)) then raise exception 'Book relationship kind is not allowed by book type'; end if;
 select project_id,author_id,book_type,node_role,relationship_kind,parent_book_id into current_project,current_author,current_type,current_role,current_kind,current_parent from public.command_center_books_current b where b.owner_id=new.owner_id and b.book_id=new.book_id;
 if current_project is not null and (current_project<>new.project_id or current_author<>new.author_id or current_type<>new.book_type or current_role<>new.node_role or current_kind<>new.relationship_kind or current_parent is distinct from new.parent_book_id) then raise exception 'Canonical book hierarchy lineage cannot be silently substituted'; end if;
 if new.parent_book_id is not null then select relationship_kind,node_role into parent_kind,parent_role from public.command_center_books_current p where p.owner_id=new.owner_id and p.book_id=new.parent_book_id; if parent_role is null or parent_role<>'container' then raise exception 'Book parent must be an existing owner-scoped container'; end if; select count(*) into sibling_count from public.command_center_books_current s where s.owner_id=new.owner_id and s.parent_book_id=new.parent_book_id and s.book_id<>new.book_id and s.sequence=new.sequence; if sibling_count>0 then raise exception 'Sibling sequence is already occupied'; end if; if parent_kind='trilogy' and new.node_role='work' then if new.sequence>3 then raise exception 'Trilogy work sequence cannot exceed three'; end if; select count(*) into sibling_count from public.command_center_books_current s where s.owner_id=new.owner_id and s.parent_book_id=new.parent_book_id and s.book_id<>new.book_id and s.node_role='work'; if sibling_count>=3 then raise exception 'Trilogy cannot contain more than three direct work nodes'; end if; end if; end if;
 return new;
end $$;
drop trigger if exists command_center_book_registry_validate on public.command_center_book_registry_history; create trigger command_center_book_registry_validate before insert on public.command_center_book_registry_history for each row execute function public.command_center_validate_book_registry_insert();
create or replace function public.command_center_reject_book_registry_evidence_mutation() returns trigger language plpgsql set search_path to 'public' as $$ begin raise exception 'Book registry evidence is immutable'; end $$;
drop trigger if exists command_center_book_author_history_immutable on public.command_center_book_author_identity_history; create trigger command_center_book_author_history_immutable before update or delete on public.command_center_book_author_identity_history for each row execute function public.command_center_reject_book_registry_evidence_mutation();
drop trigger if exists command_center_book_type_history_immutable on public.command_center_book_type_history; create trigger command_center_book_type_history_immutable before update or delete on public.command_center_book_type_history for each row execute function public.command_center_reject_book_registry_evidence_mutation();
drop trigger if exists command_center_book_registry_history_immutable on public.command_center_book_registry_history; create trigger command_center_book_registry_history_immutable before update or delete on public.command_center_book_registry_history for each row execute function public.command_center_reject_book_registry_evidence_mutation();
alter table public.command_center_book_author_identity_history enable row level security; alter table public.command_center_book_type_history enable row level security; alter table public.command_center_book_registry_history enable row level security;
revoke all on table public.command_center_book_author_identity_history,public.command_center_book_type_history,public.command_center_book_registry_history from public,anon,authenticated; grant select,insert on table public.command_center_book_author_identity_history,public.command_center_book_type_history,public.command_center_book_registry_history to authenticated; grant select on table public.command_center_book_authors_current,public.command_center_book_types_current,public.command_center_books_current to authenticated;
create policy p11_1_book_author_owner on public.command_center_book_author_identity_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p11_1_book_type_owner on public.command_center_book_type_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p11_1_book_registry_owner on public.command_center_book_registry_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
